catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    //Type appropriate comment here, and begin script below
    if (isLoading || newValue == "") {
        return;
    }

    if (newValue !== "true") {
        return;
    }

    var booking_for = g_form.getValue('who_are_you_booking_for');
    var already_an_app = g_form.getValue('already_have_an_active_appointment');

    if (already_an_app === "true") {
        if ((booking_for === "myself" || booking_for === "")) {
            spModal.alert(getMessage('x_hccc_hoc_ohs.already_have_an_appointment') + '<br /><br /><a href="services?id=ticket&is_new_order=true&table=x_hccc_hoc_ohs_vaccination_appointment&sys_id=185120351b6fca14813f844fdd4bcb6b" target="_blank">Reschedule</a>').then(function(answer) {
                //c.simple = answer;
            });
            //g_form.addErrorMessage(getMessage('x_hccc_hoc_ohs.already_have_an_appointment'));
        } else if (booking_for === "internal" || booking_for === "mp" || booking_for === "pps") {
            g_form.addErrorMessage(getMessage('x_hccc_hoc_ohs.selected_employee_already_have_an_appointment'));
        } else if (booking_for === "external") {
            g_form.addErrorMessage(getMessage('x_hccc_hoc_ohs.selected_email_already_have_an_appointment'));
        }
    }

}
